#!/usr/bin/env python3
"""Rename Fortress analyzed-cache files from one tree's path hash to another's.

NamingCzar.deCaseName names each cached AST <ApiName>-<hex(sourcePath.hashCode() & 0x7fffffff)>
where sourcePath is the canonical path of the .fss/.fsi.  Given the old home and the new home,
compute both hashes for every library source and rename the files in the cache dir.

usage: rehash_cache.py OLD_HOME NEW_HOME CACHES_DIR
"""
import os, sys, re

def jhash(s):
    h = 0
    for ch in s:
        h = (31 * h + ord(ch)) & 0xFFFFFFFF
    return format(h & 0x7fffffff, 'x')

old_home, new_home, caches = [os.path.realpath(a) for a in sys.argv[1:4]]
src_dirs = ['ProjectFortress/LibraryBuiltin', 'Library', 'ProjectFortress/test_library']
mapping = {}
for d in src_dirs:
    full = os.path.join(new_home, d)
    for root, _, files in os.walk(full):
        for f in files:
            if f.endswith(('.fss', '.fsi')):
                newp = os.path.join(root, f)
                oldp = old_home + newp[len(new_home):]
                mapping[jhash(oldp)] = jhash(newp)

pat = re.compile(r'^(.*)-([0-9a-f]+)(\.[a-z]+)$')
renamed = skipped = 0
for sub in ['analyzed_cache', 'analyzed_cache/depends']:
    d = os.path.join(caches, sub)
    if not os.path.isdir(d):
        continue
    for f in os.listdir(d):
        m = pat.match(f)
        if not m:
            continue
        name, hx, ext = m.groups()
        if hx in mapping and mapping[hx] != hx:
            os.rename(os.path.join(d, f), os.path.join(d, name + '-' + mapping[hx] + ext))
            renamed += 1
        else:
            skipped += 1
print(f'renamed {renamed}, left {skipped} (mapped {len(mapping)} library sources)')

